class Bird {
    func sound() -> String { "Tweet" }
}
class Duck: Bird {
    override func sound() -> String { "Quack" }
}
let b: Bird = Duck()
print(b.sound())

class Appliance {
    var isOn = false
    func turnOn() { isOn = true }
}
class Oven: Appliance {
    override func turnOn() {
        super.turnOn()
        print("Preheating")
    }
}
let oven = Oven()
oven.turnOn()
print(oven.isOn)

class Base {
    var count = 10
}
class Child: Base {
    var multiplier = 2
}
let c = Child()
print(c.count * c.multiplier)

class Rectangle {
    var width = 4
    var height = 5
    var area: Int { width * height }
}
class Square: Rectangle {
    override var area: Int { width * width }
}
let s = Square()
s.width = 6
s.height = 10
print(s.area)

class Speaker {
    var volume = 5 {
        didSet { print("Base didSet: \(volume)") }
    }
}
class SmartSpeaker: Speaker {
    override var volume: Int {
        didSet { print("Sub didSet: \(volume)") }
    }
}
let sp = SmartSpeaker()
sp.volume = 8

class Person {
    var name: String
    init(name: String) { self.name = name }
}
class Employee: Person {
    var id: Int
    init(name: String, id: Int) {
        self.id = id
        super.init(name: name)
    }
}
let e = Employee(name: "Sam", id: 42)
print("\(e.name)-\(e.id)")

class Greeter {
    func sayHello() -> String { "Hello" }
}
class FriendlyGreeter: Greeter {
    override func sayHello() -> String {
        return super.sayHello() + " Friend"
    }
}
let g = FriendlyGreeter()
print(g.sayHello())

class Animal {
    final func sleep() -> String { "Sleeping" }
}
class Cat: Animal {
    func purr() -> String { "Purring" }
}
let c = Cat()
print("\(c.sleep()) and \(c.purr())")

