class Document {
    var title: String
    init(title: String) { self.title = title }
}
class SecureDocument: Document {
    var clearanceLevel: Int
    init(title: String, clearanceLevel: Int) {
        self.clearanceLevel = clearanceLevel
        super.init(title: title)
    }
}
let doc = SecureDocument(title: "Top Secret", clearanceLevel: 5)
print("\(doc.title) (Level \(doc.clearanceLevel))")

